import pandas as pd
import numpy as np

# Load the dataset
df = pd.read_csv(r'C:\\repos\\ExcelCopilotResearch\\ADA_benchmark_evaluation\\kaggle_source\\Dataset\\fifa-21-messy-raw-dataset-for-cleaning-exploring\\Repo_Data\\fifa21 raw data v2.csv')

# Display the first 5 rows of the dataset
print("Dataset Preview:")
print(df.head())

# Identify and display the columns that need to be converted to numerical forms
columns_to_convert = ['Height', 'Weight', 'Value', 'Wage', 'Release Clause']
print("\nColumns to Convert:")
print(df[columns_to_convert].head())

# Define conversion functions for each column
def convert_height(height):
    if isinstance(height, str): 
        if 'cm' in height:
            return float(height.replace('cm', '').strip())
        elif "'" in height and '"' in height:
            feet, inches = height.split("'")
            inches = inches.replace('"', '').strip()
            feet = float(feet.strip())
            inches = float(inches)
            return (feet * 12 + inches) * 2.54
    return np.nan

def convert_weight(weight):
    if isinstance(weight, str):
        if 'kg' in weight:
            return float(weight.replace('kg', '').strip())
        elif 'lbs' in weight:
            return float(weight.replace('lbs', '').strip()) * 0.453592
    return np.nan

def unitless_values(values):
    if isinstance(values, str):
        values = values.replace('€', '').replace('$', '').replace('£', '').strip()
    return values

def values_numeric(value):
    if isinstance(value, str):
        value = value.lower().replace('€', '').replace(',', '')
        if 'm' in value:
            return float(value.replace('m', '').strip()) * 1000000
        elif 'k' in value:
            return float(value.replace('k', '').strip()) * 1000
        else:
            return float(value)
    return np.nan

# Apply conversion functions to the columns
df['Height'] = df['Height'].apply(convert_height).round().astype('Int64')
df['Weight'] = df['Weight'].apply(convert_weight).round().astype('Int64')
df['Value'] = df['Value'].apply(unitless_values).apply(values_numeric)
df['Wage'] = df['Wage'].apply(unitless_values).apply(values_numeric)
df['Release Clause'] = df['Release Clause'].apply(unitless_values).apply(values_numeric)

# Display the converted columns to verify the changes
print("\nConverted Columns:")
print(df[columns_to_convert].head())

