        elif 'k' in value:
            return float(value.replace('k', '').strip()) * 1000
        else:
            return float(value)
    return np.nan

df['Value'] = df['Value'].apply(values_numeric)
df['Wage'] = df['Wage'].apply(values_numeric)
df['Release Clause'] = df['Release Clause'].apply(values_numeric)

